Both workers acquire the locks in the same order (`a` then `b`), preventing a circular wait. The scope ensures both locks are released before each worker returns.

```rust
use std::sync::{Arc, Mutex};
use std::thread;

fn t1(a: Arc<Mutex<()>>, b: Arc<Mutex<()>>) -> u8 {
    {
        let _guard_a = a.lock().unwrap();
        let _guard_b = b.lock().unwrap();
        // Critical work requiring both a and b.
    }
    1
}

fn t2(a: Arc<Mutex<()>>, b: Arc<Mutex<()>>) -> u8 {
    {
        let _guard_a = a.lock().unwrap();
        let _guard_b = b.lock().unwrap();
        // Critical work requiring both a and b.
    }
    1
}

fn main() {
    let a = Arc::new(Mutex::new(()));
    let b = Arc::new(Mutex::new(()));

    let a1 = Arc::clone(&a);
    let b1 = Arc::clone(&b);
    let handle_t1 = thread::spawn(move || t1(a1, b1));

    let a2 = Arc::clone(&a);
    let b2 = Arc::clone(&b);
    let handle_t2 = thread::spawn(move || t2(a2, b2));

    let result_t1 = handle_t1.join().unwrap();
    let result_t2 = handle_t2.join().unwrap();

    println!("DONE t1={result_t1} t2={result_t2}");
}
